CREATE TABLE sys_user(id CHAR(36) PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,name VARCHAR(80) NOT NULL,role VARCHAR(24) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,auth_version INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL);
CREATE TABLE sys_role(code VARCHAR(24) PRIMARY KEY,name VARCHAR(40) NOT NULL);
CREATE TABLE sys_permission(code VARCHAR(80) PRIMARY KEY,name VARCHAR(80) NOT NULL);
CREATE TABLE sys_user_role(user_id CHAR(36) NOT NULL,role_code VARCHAR(24) NOT NULL,PRIMARY KEY(user_id,role_code),FOREIGN KEY(user_id) REFERENCES sys_user(id),FOREIGN KEY(role_code) REFERENCES sys_role(code));
CREATE TABLE sys_role_permission(role_code VARCHAR(24),permission_code VARCHAR(80),PRIMARY KEY(role_code,permission_code),FOREIGN KEY(role_code) REFERENCES sys_role(code),FOREIGN KEY(permission_code) REFERENCES sys_permission(code));
CREATE TABLE laboratory(id CHAR(36) PRIMARY KEY,name VARCHAR(100) NOT NULL,location VARCHAR(160) NOT NULL,open_start INT NOT NULL DEFAULT 8,open_end INT NOT NULL DEFAULT 22,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(3) NOT NULL,CHECK(open_start>=0 AND open_end<=24 AND open_start<open_end));
CREATE TABLE lab_staff_scope(user_id CHAR(36),lab_id CHAR(36),PRIMARY KEY(user_id,lab_id),FOREIGN KEY(user_id) REFERENCES sys_user(id),FOREIGN KEY(lab_id) REFERENCES laboratory(id));
CREATE TABLE lab_calendar(id CHAR(36) PRIMARY KEY,lab_id CHAR(36) NOT NULL,local_date DATE NOT NULL,is_open BOOLEAN NOT NULL,reason VARCHAR(255),UNIQUE(lab_id,local_date),FOREIGN KEY(lab_id) REFERENCES laboratory(id));
CREATE TABLE equipment_category(id CHAR(36) PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE equipment(id CHAR(36) PRIMARY KEY,asset_no VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,model VARCHAR(120) NOT NULL,category_id CHAR(36) NOT NULL,lab_id CHAR(36) NOT NULL,purchased_on DATE,description TEXT,enabled BOOLEAN NOT NULL DEFAULT TRUE,version INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL,FOREIGN KEY(lab_id) REFERENCES laboratory(id),FOREIGN KEY(category_id) REFERENCES equipment_category(id),INDEX(lab_id,enabled));
CREATE TABLE reservation(id CHAR(36) PRIMARY KEY,reservation_no VARCHAR(50) NOT NULL UNIQUE,equipment_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,lab_id CHAR(36) NOT NULL,starts_at DATETIME(3) NOT NULL,ends_at DATETIME(3) NOT NULL,purpose VARCHAR(600) NOT NULL,status VARCHAR(32) NOT NULL,reviewed_by CHAR(36),reason VARCHAR(600),version INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL,FOREIGN KEY(equipment_id) REFERENCES equipment(id),FOREIGN KEY(user_id) REFERENCES sys_user(id),FOREIGN KEY(lab_id) REFERENCES laboratory(id),CHECK(starts_at<ends_at),INDEX(equipment_id,status,starts_at,ends_at),INDEX(user_id,created_at),INDEX(lab_id,status));
CREATE TABLE loan_record(id CHAR(36) PRIMARY KEY,loan_no VARCHAR(50) NOT NULL UNIQUE,reservation_id CHAR(36) NOT NULL UNIQUE,equipment_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,lab_id CHAR(36) NOT NULL,issued_by CHAR(36) NOT NULL,issued_at DATETIME(3) NOT NULL,due_at DATETIME(3) NOT NULL,returned_at DATETIME(3),return_note TEXT,return_photo_ids JSON,status VARCHAR(24) NOT NULL,checked_by CHAR(36),checked_at DATETIME(3),active_equipment_id CHAR(36) GENERATED ALWAYS AS (CASE WHEN returned_at IS NULL THEN equipment_id ELSE NULL END) STORED,UNIQUE(active_equipment_id),FOREIGN KEY(reservation_id) REFERENCES reservation(id),FOREIGN KEY(equipment_id) REFERENCES equipment(id),FOREIGN KEY(user_id) REFERENCES sys_user(id),INDEX(lab_id,status,due_at),INDEX(user_id,issued_at));
CREATE TABLE fault_ticket(id CHAR(36) PRIMARY KEY,ticket_no VARCHAR(50) NOT NULL UNIQUE,equipment_id CHAR(36) NOT NULL,lab_id CHAR(36) NOT NULL,loan_id CHAR(36),reporter_id CHAR(36) NOT NULL,title VARCHAR(160) NOT NULL,description TEXT NOT NULL,photo_ids JSON,severity VARCHAR(20) NOT NULL DEFAULT 'NORMAL',affects_use BOOLEAN,status VARCHAR(32) NOT NULL,assignee_id CHAR(36),verified_by CHAR(36),accepted_at DATETIME(3),repair_started_at DATETIME(3),repair_submitted_at DATETIME(3),closed_at DATETIME(3),resolution TEXT,labor_minutes INT NOT NULL DEFAULT 0,cost_amount DECIMAL(12,2) NOT NULL DEFAULT 0,version INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL,FOREIGN KEY(equipment_id) REFERENCES equipment(id),FOREIGN KEY(lab_id) REFERENCES laboratory(id),FOREIGN KEY(reporter_id) REFERENCES sys_user(id),FOREIGN KEY(assignee_id) REFERENCES sys_user(id),FOREIGN KEY(loan_id) REFERENCES loan_record(id),INDEX(lab_id,status,created_at),INDEX(assignee_id,status));
CREATE TABLE equipment_block(id CHAR(36) PRIMARY KEY,equipment_id CHAR(36) NOT NULL,source_type VARCHAR(24) NOT NULL,source_id CHAR(36) NOT NULL,reason VARCHAR(600) NOT NULL,starts_at DATETIME(3) NOT NULL,ends_at DATETIME(3),UNIQUE(source_type,source_id),FOREIGN KEY(equipment_id) REFERENCES equipment(id),INDEX(equipment_id,ends_at,starts_at));
CREATE TABLE business_event(id CHAR(36) PRIMARY KEY,business_type VARCHAR(24) NOT NULL,business_id CHAR(36) NOT NULL,action VARCHAR(60) NOT NULL,actor_id CHAR(36) NOT NULL,note TEXT,created_at DATETIME(3) NOT NULL,INDEX(business_type,business_id,created_at));
CREATE TABLE file_object(id CHAR(36) PRIMARY KEY,owner_id CHAR(36) NOT NULL,storage_key VARCHAR(160) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,mime_type VARCHAR(100) NOT NULL,size_bytes BIGINT NOT NULL,sha256 CHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL,FOREIGN KEY(owner_id) REFERENCES sys_user(id));
CREATE TABLE notification(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,title VARCHAR(160) NOT NULL,content TEXT NOT NULL,business_type VARCHAR(30),business_id CHAR(36),dedupe_key VARCHAR(200) NOT NULL,read_at DATETIME(3),created_at DATETIME(3) NOT NULL,UNIQUE(user_id,dedupe_key),FOREIGN KEY(user_id) REFERENCES sys_user(id),INDEX(user_id,read_at,created_at));
CREATE TABLE knowledge_document(id CHAR(36) PRIMARY KEY,title VARCHAR(160) NOT NULL,category VARCHAR(80) NOT NULL DEFAULT '',model VARCHAR(120) NOT NULL DEFAULT '',lab_id CHAR(36),visibility VARCHAR(24) NOT NULL DEFAULT 'PUBLIC',enabled BOOLEAN NOT NULL DEFAULT TRUE,published_version_id CHAR(36),created_by CHAR(36) NOT NULL,created_at DATETIME(3) NOT NULL,FOREIGN KEY(lab_id) REFERENCES laboratory(id));
CREATE TABLE knowledge_version(id CHAR(36) PRIMARY KEY,document_id CHAR(36) NOT NULL,version_no INT NOT NULL,file_id CHAR(36),text_content MEDIUMTEXT NOT NULL,status VARCHAR(24) NOT NULL,published BOOLEAN NOT NULL DEFAULT FALSE,chunk_count INT NOT NULL DEFAULT 0,error TEXT,created_at DATETIME(3) NOT NULL,UNIQUE(document_id,version_no),FOREIGN KEY(document_id) REFERENCES knowledge_document(id),FOREIGN KEY(file_id) REFERENCES file_object(id));
CREATE TABLE knowledge_chunk(id CHAR(36) PRIMARY KEY,version_id CHAR(36) NOT NULL,chunk_index INT NOT NULL,text_content TEXT NOT NULL,locator VARCHAR(160) NOT NULL,UNIQUE(version_id,chunk_index),FOREIGN KEY(version_id) REFERENCES knowledge_version(id));
CREATE TABLE conversation(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,title VARCHAR(100) NOT NULL,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,FOREIGN KEY(user_id) REFERENCES sys_user(id),INDEX(user_id,updated_at));
CREATE TABLE chat_message(id CHAR(36) PRIMARY KEY,conversation_id CHAR(36) NOT NULL,role VARCHAR(20) NOT NULL,content MEDIUMTEXT NOT NULL,attachments JSON,cards JSON,citations JSON,run_id CHAR(36),created_at DATETIME(3) NOT NULL,FOREIGN KEY(conversation_id) REFERENCES conversation(id),INDEX(conversation_id,created_at));
CREATE TABLE ai_run(id CHAR(36) PRIMARY KEY,conversation_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,status VARCHAR(24) NOT NULL,mode VARCHAR(16) NOT NULL,query MEDIUMTEXT NOT NULL,photo_ids JSON,context_json JSON,result_json JSON,error TEXT,grant_hash CHAR(64),started_at DATETIME(3) NOT NULL,finished_at DATETIME(3),UNIQUE(conversation_id,id),FOREIGN KEY(conversation_id) REFERENCES conversation(id),FOREIGN KEY(user_id) REFERENCES sys_user(id));
CREATE TABLE ai_tool_event(id CHAR(36) PRIMARY KEY,run_id CHAR(36) NOT NULL,tool_name VARCHAR(80) NOT NULL,summary VARCHAR(500),duration_ms BIGINT,created_at DATETIME(3) NOT NULL,FOREIGN KEY(run_id) REFERENCES ai_run(id));
CREATE TABLE job_task(id CHAR(36) PRIMARY KEY,type VARCHAR(30) NOT NULL,business_id CHAR(36) NOT NULL,status VARCHAR(24) NOT NULL,error TEXT,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL);
CREATE TABLE idempotency_record(user_id CHAR(36) NOT NULL,operation VARCHAR(100) NOT NULL,idempotency_key VARCHAR(100) NOT NULL,request_hash CHAR(64) NOT NULL,response_json MEDIUMTEXT NOT NULL,created_at DATETIME(3) NOT NULL,PRIMARY KEY(user_id,operation,idempotency_key));
CREATE TABLE system_setting(setting_key VARCHAR(100) PRIMARY KEY,value_text MEDIUMTEXT NOT NULL,updated_at DATETIME(3) NOT NULL);
CREATE TABLE audit_log(id CHAR(36) PRIMARY KEY,actor_id CHAR(36) NOT NULL,action VARCHAR(100) NOT NULL,target_id VARCHAR(100),note TEXT,created_at DATETIME(3) NOT NULL,INDEX(actor_id,created_at));
